"""Event types and the simulation clock for the capstone trading simulator."""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum, auto


class EventType(Enum):
 MARKET_DATA = auto()
 ORDER = auto()
 FILL = auto()
 TIMER = auto()


@dataclass(frozen=True)
class MarketDataEvent:
 timestamp: int # simulation clock in nanoseconds; non-decreasing
 symbol: str
 bid: float
 ask: float


@dataclass(frozen=True)
class OrderEvent:
 timestamp: int
 symbol: str
 side: str # "buy" | "sell"
 quantity: int # shares; positive
 limit_price: float | None # None => market order


@dataclass(frozen=True)
class FillEvent:
 timestamp: int
 order_timestamp: int
 symbol: str
 side: str
 quantity: int
 price: float
 commission: float


class LookAheadError(AssertionError):
 """Raised when the simulation is fed an event older than the clock."""


class SimulationClock:
 """Monotonic high-water mark of processed event timestamps.

 Every handler must call advance_to(event.timestamp) BEFORE acting on the
 event; any attempt to act on stale data raises.
 """

 def __init__(self) -> None:
 self._now: int = -1

 @property
 def now(self) -> int:
 return self._now

 def advance_to(self, timestamp: int) -> None:
 if timestamp < self._now:
 raise LookAheadError(
 f"event timestamp {timestamp} precedes clock {self._now}"
 )
 self._now = timestamp
